import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar';
import Home from './pages/Home';
import Products from './pages/Products';
import Cart from './pages/Cart';
import Checkout from './pages/Checkout';
import Login from './pages/Login';
import Register from './pages/Register';
import Account from './pages/Account';
import Orders from './pages/Orders';
import Success from './pages/Success';
import OrderDetails from './pages/OrderDetails';
import Wishlist from './pages/Wishlist';
import ForgotPassword from './pages/ForgotPassword';
import ResetPassword from './pages/ResetPassword';
import Admin from './pages/Admin';
import Footer from './components/Footer';
import { getCart } from './services/api';
import { ThemeProvider } from './context/ThemeContext';

function App() {
  const [cartCount, setCartCount] = useState(0);
  const [user, setUser] = useState(null);

  useEffect(() => {
    const token = localStorage.getItem('token');
    const userInfo = localStorage.getItem('user');
    if (token && userInfo) {
      setUser(JSON.parse(userInfo));
    }
    fetchCartCount();
  }, []);

  const fetchCartCount = async () => {
    try {
      const token = localStorage.getItem('token');
      if (token) {
        const res = await getCart();
        setCartCount(res.data.totalItems);
      }
    } catch (error) {
      console.error('Error fetching cart:', error);
    }
  };

  const updateCartCount = (count) => {
    setCartCount(count);
  };

  const handleLogin = (userData) => {
    setUser(userData);
    fetchCartCount();
  };

  const handleLogout = () => {
    setUser(null);
    setCartCount(0);
    localStorage.removeItem('token');
    localStorage.removeItem('user');
  };

return (
    <ThemeProvider>
      <Router>
        <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
          <Navbar cartCount={cartCount} user={user} onLogout={handleLogout} />
          <main className="container mx-auto px-4 py-8">
            <Routes>
              <Route path="/" element={<Home />} />
              <Route path="/products" element={<Products />} />
              <Route 
                path="/cart" 
                element={<Cart cartCount={updateCartCount} />} 
              />
              <Route 
                path="/checkout" 
                element={<Checkout cartCount={updateCartCount} />} 
              />
              <Route 
                path="/login" 
                element={<Login onLogin={handleLogin} />} 
              />
              <Route 
                path="/register" 
                element={<Register onRegister={handleLogin} />} 
              />
              <Route 
                path="/account" 
                element={<Account user={user} onUpdate={handleLogin} />} 
              />
<Route path="/success" element={<Success />} />
              <Route path="/order/:id" element={<OrderDetails />} />
              <Route path="/wishlist" element={<Wishlist />} />
              <Route path="/forgot-password" element={<ForgotPassword />} />
<Route path="/reset-password/:token" element={<ResetPassword />} />
              <Route path="/admin" element={<Admin />} />
</Routes>
          </main>
          <Footer />
        </div>
      </Router>
    </ThemeProvider>
  );
}

export default App;
